import Foundation

/// How far the phone remote seeks, in both directions.
public let remoteSeekSeconds = 10

/// The payload envelope consumed by the control plane and the TV player. The `id` is generated by the phone so a retried send
/// cannot create a second command.
public func remoteCommandBody(command: String, targetDeviceId: String, videoId: String? = nil, arguments: [String: Any] = [:],
                              id: String = UUID().uuidString.lowercased()) throws -> [String: Any] {
    guard !targetDeviceId.trimmingCharacters(in: .whitespaces).isEmpty else { throw RemoteCommandError.noTarget }
    var payload = arguments
    if let videoId { payload["videoId"] = videoId }
    return ["id": id, "command": command, "target_device_id": targetDeviceId, "payload": payload]
}

public enum RemoteCommandError: Error { case noTarget }

public enum TargetResult: Sendable, Equatable {
    /// `offline`: the control plane says this TV doesn't have Cablegram open. `switchedFrom`: the selected TV wasn't on and this,
    /// the only TV that is, was chosen instead.
    case target(deviceId: String, name: String, offline: Bool = false, switchedFrom: String? = nil)
    case failed(String)
}

/// Picks the TV a remote command goes to. A selected TV that the account no longer lists is a failure: a command must never fall
/// back to a different TV. Only with nothing selected does the first account TV serve as the default. `household` is nil when it
/// could not be loaded.
///
/// A TV paired before device IDs were stored has none to match. It can only mean the account's TV when there is exactly one; with
/// several, the person must choose rather than risk another room.
///
/// The one exception to "never a different TV": the selected TV isn't on (it could not take the command anyway) and exactly one TV
/// of the account is. That TV is the one in use, so the command goes there and says so. With none or several on, nothing is guessed.
public func resolveTarget(selected: PairedTv?, household: [MeDevice]?) -> TargetResult {
    let none = TargetResult.failed("No TV is paired with this household. Pair a TV to use the remote.")
    func label(_ d: MeDevice) -> String { d.displayName.flatMap { $0.trimmingCharacters(in: .whitespaces).isEmpty ? nil : $0 } ?? "TV" }
    guard let household else {
        if let selected {
            if let id = selected.deviceId { return .target(deviceId: id, name: selected.name) }
            return .failed("Can't reach the control service to find \(selected.name). Check your connection.")
        }
        return none
    }
    if let selected {
        guard let selectedId = selected.deviceId else {
            if household.count == 1 { return .target(deviceId: household[0].id, name: selected.name) }
            return household.isEmpty ? none : .failed("Choose which TV to control in Settings.")
        }
        guard let chosen = household.first(where: { $0.id == selectedId }) else { return .failed("\(selected.name) is no longer connected. Choose a TV in Settings.") }
        let on = household.filter { $0.online == true }
        if chosen.online == false && on.count == 1 { return .target(deviceId: on[0].id, name: label(on[0]), switchedFrom: selected.name) }
        return .target(deviceId: chosen.id, name: selected.name, offline: chosen.online == false)
    }
    let ons = household.filter { $0.online == true }
    guard let pick = ons.count == 1 ? ons[0] : household.first else { return none }
    return .target(deviceId: pick.id, name: label(pick), offline: pick.online == false)
}

/// Plain-language text for a reason the TV (or the server's expiry) rejected a command.
public func rejectionMessage(_ reason: String?, tvName: String) -> String {
    switch reason {
    case "profile_required": "Choose a profile on the TV first."
    case "title_unavailable": "\(tvName) can't find that title."
    case "screen_unavailable": "\(tvName) can't do that on its current screen."
    case "expired": "\(tvName) didn't respond in time. Check the TV."
    case "execution_interrupted": "\(tvName) was interrupted. Try again."
    case "superseded": "Another title was started on \(tvName)."
    case "cancelled": "Playback was cancelled on \(tvName)."
    case "not_applicable", "not_handled", "player_closed": "Nothing is playing on \(tvName)."
    case "session_closed", "inactive_account": "\(tvName) is signed in to another account or closed the session."
    case "invalid_payload": "\(tvName) didn't understand that command. Update the app on the TV."
    default: "\(tvName) couldn't do that."
    }
}

/// What the mini-player shows. `canToggle` is false while a title is starting, as there is nothing to pause yet.
public struct MiniPlayerLines: Sendable, Equatable {
    public var title: String
    public var caption: String
    public var canToggle: Bool
}

/// The title being started takes over the mini-player until the TV answers, so its "Starting…" status never reads as a status of
/// the title that was playing before. Nil when there is nothing to show.
public func miniPlayerLines(playing: String?, starting: String?, tvName: String, status: String?) -> MiniPlayerLines? {
    if let starting { return MiniPlayerLines(title: starting, caption: status ?? tvName, canToggle: false) }
    if let playing { return MiniPlayerLines(title: playing, caption: status ?? tvName, canToggle: true) }
    return nil
}
